/**
 * Pre-compiled Gemini TTS Voice Audio Buffers
 * Guaranteed 0ms in-memory availability across all serverless containers
 */

const PREBUILT_AUDIO_BASE64: Record<string, string> = {
  "welcome_greeting": "",
  "silence_prompt": "",
  "timeout_goodbye": "",
};

export function getPrebuiltAudioBuffer(name: string): Buffer | undefined {
  const clean = name.replace(/\.wav$/i, "");
  const b64 = PREBUILT_AUDIO_BASE64[clean];
  if (!b64) return undefined;
  return Buffer.from(b64, "base64");
}
